INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes, origin_year, origin_figure, history_intro) VALUES
('33333333-0004-0001-0001-000000000001', '22222222-0001-0001-0001-000000000004', 'What is a Fraction?', 'Discover how ancient Egyptians divided bread and land using fractions', 1, 'tutorial', 15, 5, -1800, 'Ahmes',
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0401-0001-0001-000000000001', '33333333-0004-0001-0001-000000000001', 'multiple_choice', 'easy', 'What does the word "fraction" come from?', NULL, '[{"id":"a","text":"Latin for counting"},{"id":"b","text":"Latin for breaking"},{"id":"c","text":"Greek for sharing"},{"id":"d","text":"Arabic for dividing"}]'::jsonb, '"b"'::jsonb, 'Correct! "Fraction" comes from the Latin "fractio" meaning "a breaking" — because a fraction breaks a whole into parts.', 'Think about what you do to a whole when you create a fraction', 5, 1),
('44444444-0401-0001-0001-000000000002', '33333333-0004-0001-0001-000000000001', 'multiple_choice', 'easy', 'In the fraction 3/4, what is the number 3 called?', NULL, '[{"id":"a","text":"Denominator"},{"id":"b","text":"Numerator"},{"id":"c","text":"Divisor"},{"id":"d","text":"Quotient"}]'::jsonb, '"b"'::jsonb, 'The numerator (top number) tells you how many parts you have. The denominator (bottom number) tells you how many equal parts the whole is divided into.', 'The top number counts, the bottom number divides', 5, 2),
('44444444-0401-0001-0001-000000000003', '33333333-0004-0001-0001-000000000001', 'true_false', 'easy', 'True or False: Ancient Egyptians could only use fractions with 1 as the numerator (like 1/2, 1/3, 1/5).', NULL, '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"true"'::jsonb, 'True! Egyptians used "unit fractions" — fractions where the numerator is always 1. To express 2/5, they would write it as 1/3 + 1/15.', 'What were unit fractions?', 5, 3),
('44444444-0401-0001-0001-000000000004', '33333333-0004-0001-0001-000000000001', 'fill_in_blank', 'easy', 'If you cut a pizza into 8 equal slices and eat 3, what fraction of the pizza did you eat? (Write as a fraction like 3/8)', NULL, NULL, '"3/8"'::jsonb, '3 slices out of 8 total = 3/8. The denominator (8) is how many equal parts, the numerator (3) is how many you took.', 'How many slices total? How many did you eat?', 5, 4),
('44444444-0401-0001-0001-000000000005', '33333333-0004-0001-0001-000000000001', 'multiple_choice', 'easy', 'Which fraction is larger: 1/3 or 1/4?', NULL, '[{"id":"a","text":"1/3"},{"id":"b","text":"1/4"},{"id":"c","text":"They are equal"},{"id":"d","text":"Cannot be compared"}]'::jsonb, '"a"'::jsonb, '1/3 is larger! When the numerator is the same, the smaller the denominator, the bigger the fraction. Cutting something into 3 pieces gives bigger pieces than cutting into 4.', 'If you split a cake into fewer pieces, each piece is...', 5, 5)
INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes, origin_year, origin_figure, history_intro) VALUES
('33333333-0004-0001-0001-000000000002', '22222222-0001-0001-0001-000000000004', 'Comparing Fractions', 'Learn to compare fractions using common denominators and cross-multiplication', 2, 'practice', 15, 5, NULL, NULL, NULL)
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0402-0001-0001-000000000001', '33333333-0004-0001-0001-000000000002', 'multiple_choice', 'easy', 'Which is larger: 2/5 or 3/5?', NULL, '[{"id":"a","text":"2/5"},{"id":"b","text":"3/5"},{"id":"c","text":"They are equal"},{"id":"d","text":"Cannot tell"}]'::jsonb, '"b"'::jsonb, '3/5 is larger. When fractions have the same denominator, just compare the numerators. 3 > 2, so 3/5 > 2/5.', 'Same denominator — just look at the top numbers', 5, 1),
('44444444-0402-0001-0001-000000000002', '33333333-0004-0001-0001-000000000002', 'multiple_choice', 'easy', 'Which is larger: 3/4 or 5/8?', NULL, '[{"id":"a","text":"3/4"},{"id":"b","text":"5/8"},{"id":"c","text":"They are equal"},{"id":"d","text":"Cannot tell"}]'::jsonb, '"a"'::jsonb, '3/4 = 6/8, and 6/8 > 5/8. Converting to the same denominator makes comparison easy!', 'Try converting 3/4 so it has a denominator of 8', 5, 2),
('44444444-0402-0001-0001-000000000003', '33333333-0004-0001-0001-000000000002', 'true_false', 'easy', 'True or False: 1/2 is equal to 3/6.', NULL, '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"true"'::jsonb, 'True! 1/2 and 3/6 are equivalent fractions. If you multiply both the numerator and denominator of 1/2 by 3, you get 3/6.', 'Multiply top and bottom of 1/2 by the same number', 5, 3),
('44444444-0402-0001-0001-000000000004', '33333333-0004-0001-0001-000000000002', 'fill_in_blank', 'easy', 'Simplify the fraction 4/8 to its lowest terms. (Write as a fraction)', NULL, NULL, '"1/2"'::jsonb, '4/8 simplifies to 1/2. Divide both numerator and denominator by their greatest common factor (4).', 'What number divides evenly into both 4 and 8?', 5, 4),
('44444444-0402-0001-0001-000000000005', '33333333-0004-0001-0001-000000000002', 'multiple_choice', 'medium', 'Put these fractions in order from smallest to largest: 1/2, 2/3, 1/4', NULL, '[{"id":"a","text":"1/4, 1/2, 2/3"},{"id":"b","text":"1/2, 1/4, 2/3"},{"id":"c","text":"2/3, 1/2, 1/4"},{"id":"d","text":"1/4, 2/3, 1/2"}]'::jsonb, '"a"'::jsonb, '1/4 = 0.25, 1/2 = 0.50, 2/3 ≈ 0.67. So the order is 1/4, 1/2, 2/3.', 'Try converting each fraction to a decimal', 10, 5)
INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes, origin_year, origin_figure, history_intro) VALUES
('33333333-0004-0001-0001-000000000003', '22222222-0001-0001-0001-000000000004', 'Adding & Subtracting Fractions', 'Master adding and subtracting fractions with same and different denominators', 3, 'practice', 15, 7, NULL, NULL, NULL)
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0403-0001-0001-000000000001', '33333333-0004-0001-0001-000000000003', 'fill_in_blank', 'easy', 'What is 1/4 + 2/4? (Write as a fraction)', '\\frac{1}{4} + \\frac{2}{4} = ?', NULL, '"3/4"'::jsonb, 'When denominators are the same, just add the numerators: 1 + 2 = 3. The answer is 3/4.', 'Same denominators — add the top numbers', 5, 1),
('44444444-0403-0001-0001-000000000002', '33333333-0004-0001-0001-000000000003', 'fill_in_blank', 'easy', 'What is 5/6 - 2/6? (Write as a simplified fraction)', '\\frac{5}{6} - \\frac{2}{6} = ?', NULL, '"1/2"'::jsonb, '5/6 - 2/6 = 3/6, which simplifies to 1/2.', 'Subtract the numerators, then simplify', 5, 2),
('44444444-0403-0001-0001-000000000003', '33333333-0004-0001-0001-000000000003', 'multiple_choice', 'medium', 'What is 1/3 + 1/4?', '\\frac{1}{3} + \\frac{1}{4} = ?', '[{"id":"a","text":"2/7"},{"id":"b","text":"7/12"},{"id":"c","text":"1/7"},{"id":"d","text":"5/12"}]'::jsonb, '"b"'::jsonb, 'Find a common denominator: 1/3 = 4/12 and 1/4 = 3/12. So 4/12 + 3/12 = 7/12.', 'Find the least common denominator of 3 and 4', 10, 3),
('44444444-0403-0001-0001-000000000004', '33333333-0004-0001-0001-000000000003', 'multiple_choice', 'medium', 'What is 3/4 - 1/3?', '\\frac{3}{4} - \\frac{1}{3} = ?', '[{"id":"a","text":"2/1"},{"id":"b","text":"5/12"},{"id":"c","text":"2/12"},{"id":"d","text":"1/4"}]'::jsonb, '"b"'::jsonb, '3/4 = 9/12 and 1/3 = 4/12. So 9/12 - 4/12 = 5/12.', 'Convert both to twelfths', 10, 4),
('44444444-0403-0001-0001-000000000005', '33333333-0004-0001-0001-000000000003', 'fill_in_blank', 'medium', 'What is 2/5 + 1/3? (Write as a fraction)', '\\frac{2}{5} + \\frac{1}{3} = ?', NULL, '"11/15"'::jsonb, '2/5 = 6/15 and 1/3 = 5/15. So 6/15 + 5/15 = 11/15.', 'The LCD of 5 and 3 is 15', 10, 5)
INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes, origin_year, origin_figure, history_intro) VALUES
('33333333-0004-0001-0001-000000000004', '22222222-0001-0001-0001-000000000004', 'Introduction to Decimals', 'Meet Simon Stevin, the man who gave us the decimal point', 4, 'tutorial', 15, 5, 1585, 'Simon Stevin',
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0404-0001-0001-000000000001', '33333333-0004-0001-0001-000000000004', 'multiple_choice', 'easy', 'Who introduced decimal fractions to Europe in 1585?', NULL, '[{"id":"a","text":"Isaac Newton"},{"id":"b","text":"Simon Stevin"},{"id":"c","text":"Leonhard Euler"},{"id":"d","text":"René Descartes"}]'::jsonb, '"b"'::jsonb, 'Simon Stevin published De Thiende (The Tenth) in 1585, showing how decimal fractions could replace common fractions for everyday calculations.', 'His pamphlet was only 36 pages long', 5, 1),
('44444444-0404-0001-0001-000000000002', '33333333-0004-0001-0001-000000000004', 'fill_in_blank', 'easy', 'Write 1/2 as a decimal.', NULL, NULL, '"0.5"'::jsonb, '1 divided by 2 equals 0.5. Half of 1 is 0.5.', 'Divide 1 by 2', 5, 2),
('44444444-0404-0001-0001-000000000003', '33333333-0004-0001-0001-000000000004', 'fill_in_blank', 'easy', 'Write 3/4 as a decimal.', NULL, NULL, '"0.75"'::jsonb, '3 divided by 4 equals 0.75.', 'Divide 3 by 4', 5, 3),
('44444444-0404-0001-0001-000000000004', '33333333-0004-0001-0001-000000000004', 'multiple_choice', 'easy', 'What does the 7 represent in 0.37?', NULL, '[{"id":"a","text":"7 ones"},{"id":"b","text":"7 tenths"},{"id":"c","text":"7 hundredths"},{"id":"d","text":"7 thousandths"}]'::jsonb, '"c"'::jsonb, 'In 0.37, the 3 is in the tenths place and the 7 is in the hundredths place. So 0.37 = 3 tenths + 7 hundredths.', 'The first digit after the decimal is tenths, the second is...', 5, 4),
('44444444-0404-0001-0001-000000000005', '33333333-0004-0001-0001-000000000004', 'true_false', 'easy', 'True or False: 0.5 and 0.50 have the same value.', NULL, '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"true"'::jsonb, 'True! 0.5 = 0.50 = 0.500. Trailing zeros after the decimal point do not change the value.', 'Does adding a zero at the end change anything?', 5, 5)
INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes, origin_year, origin_figure, history_intro) VALUES
('33333333-0004-0001-0001-000000000005', '22222222-0001-0001-0001-000000000004', 'Converting Fractions & Decimals', 'Master converting between fractions and decimals in both directions', 5, 'practice', 15, 5, NULL, NULL, NULL)
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0405-0001-0001-000000000001', '33333333-0004-0001-0001-000000000005', 'fill_in_blank', 'easy', 'Convert 0.25 to a fraction in lowest terms.', NULL, NULL, '"1/4"'::jsonb, '0.25 = 25/100 = 1/4. Divide both numerator and denominator by 25.', '0.25 means 25 hundredths', 5, 1),
('44444444-0405-0001-0001-000000000002', '33333333-0004-0001-0001-000000000005', 'fill_in_blank', 'easy', 'Convert 1/5 to a decimal.', NULL, NULL, '"0.2"'::jsonb, '1 ÷ 5 = 0.2', 'Divide the numerator by the denominator', 5, 2),
('44444444-0405-0001-0001-000000000003', '33333333-0004-0001-0001-000000000005', 'multiple_choice', 'medium', 'Which fraction is equal to 0.375?', NULL, '[{"id":"a","text":"3/8"},{"id":"b","text":"3/4"},{"id":"c","text":"5/8"},{"id":"d","text":"1/3"}]'::jsonb, '"a"'::jsonb, '0.375 = 375/1000 = 3/8. Divide both by 125.', '0.375 = 375 thousandths. Simplify 375/1000.', 10, 3),
('44444444-0405-0001-0001-000000000004', '33333333-0004-0001-0001-000000000005', 'fill_in_blank', 'medium', 'Convert 2/3 to a decimal (round to 2 decimal places).', NULL, NULL, '"0.67"'::jsonb, '2 ÷ 3 = 0.6666... which rounds to 0.67. This is a repeating decimal!', 'Divide 2 by 3', 10, 4),
('44444444-0405-0001-0001-000000000005', '33333333-0004-0001-0001-000000000005', 'multiple_choice', 'medium', 'Which of these is a repeating decimal?', NULL, '[{"id":"a","text":"1/4 = 0.25"},{"id":"b","text":"1/2 = 0.5"},{"id":"c","text":"1/3 = 0.333..."},{"id":"d","text":"1/5 = 0.2"}]'::jsonb, '"c"'::jsonb, '1/3 = 0.333... (repeating). A fraction produces a repeating decimal when its denominator has prime factors other than 2 and 5.', 'Which one never ends?', 10, 5)
INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes, origin_year, origin_figure, history_intro) VALUES
('33333333-0004-0001-0001-000000000006', '22222222-0001-0001-0001-000000000004', 'Fractions & Decimals Boss', 'Prove your mastery of fractions and decimals!', 6, 'boss_round', 30, 5, NULL, NULL, NULL)
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0406-0001-0001-000000000001', '33333333-0004-0001-0001-000000000006', 'fill_in_blank', 'medium', 'What is 2/3 + 1/6? (Write as a simplified fraction)', '\\frac{2}{3} + \\frac{1}{6} = ?', NULL, '"5/6"'::jsonb, '2/3 = 4/6, so 4/6 + 1/6 = 5/6.', 'Convert 2/3 to sixths', 10, 1),
('44444444-0406-0001-0001-000000000002', '33333333-0004-0001-0001-000000000006', 'multiple_choice', 'medium', 'Which is the correct order from smallest to largest: 0.3, 1/4, 0.35?', NULL, '[{"id":"a","text":"1/4, 0.3, 0.35"},{"id":"b","text":"0.3, 1/4, 0.35"},{"id":"c","text":"0.35, 0.3, 1/4"},{"id":"d","text":"1/4, 0.35, 0.3"}]'::jsonb, '"a"'::jsonb, '1/4 = 0.25, 0.3 = 0.30, 0.35. So the order is: 0.25, 0.30, 0.35.', 'Convert everything to decimals first', 10, 2),
('44444444-0406-0001-0001-000000000003', '33333333-0004-0001-0001-000000000006', 'fill_in_blank', 'medium', 'A recipe calls for 3/4 cup of flour. You want to make half the recipe. How much flour do you need? (Write as a fraction)', NULL, NULL, '"3/8"'::jsonb, 'Half of 3/4 = 1/2 × 3/4 = 3/8 cup.', 'Multiply 3/4 by 1/2', 10, 3),
('44444444-0406-0001-0001-000000000004', '33333333-0004-0001-0001-000000000006', 'multiple_choice', 'hard', 'What is 0.125 as a fraction in lowest terms?', NULL, '[{"id":"a","text":"1/4"},{"id":"b","text":"1/8"},{"id":"c","text":"1/5"},{"id":"d","text":"3/8"}]'::jsonb, '"b"'::jsonb, '0.125 = 125/1000. Dividing both by 125 gives 1/8.', '125 × 8 = 1000', 15, 4),
('44444444-0406-0001-0001-000000000005', '33333333-0004-0001-0001-000000000006', 'fill_in_blank', 'hard', 'What is 5/6 - 0.5? Give your answer as a fraction.', NULL, NULL, '"1/3"'::jsonb, '0.5 = 1/2. So 5/6 - 1/2 = 5/6 - 3/6 = 2/6 = 1/3.', 'Convert 0.5 to a fraction first, then subtract', 15, 5)
